// File-only controls: never import or execute the stop-capable CI controller or physical runner.
import assert from 'node:assert/strict';
import test from 'node:test';
import {existsSync, lstatSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync} from 'node:fs';
import {basename, dirname, join, resolve} from 'node:path';
import {tmpdir} from 'node:os';
import {diagnosticDirectory, diagnosticRelativePath, retainAdmission, writeAssemblyDiagnostic} from './assembly-diagnostics.mjs';
import {inventory} from './inventory.mjs';
import {sha} from './contract.mjs';
import {restoreSdk49Routing} from '../indexed-schema-mongodb/current-cbfb-contract.mjs';
import {OPERATOR_LIST_ASSEMBLY, OPERATOR_LIST_PROFILE, diagnoseOperatorListAssembly} from './source-profile.mjs';

const json = path => JSON.parse(readFileSync(path));
function fixture(t) {
    const parent = realpathSync(tmpdir()), root = mkdtempSync(join(parent, 'hapi416-assembly-test-'));
    t.after(() => {
        // Verify this exact task-owned absolute target before recursive removal on Windows.
        const actual = realpathSync(root);
        assert.equal(dirname(actual), parent); assert.ok(basename(actual).startsWith('hapi416-assembly-test-'));
        assert.equal(lstatSync(root).isSymbolicLink(), false); rmSync(actual, {recursive: true});
    });
    mkdirSync(join(root, 'build', 'nested'), {recursive: true}); mkdirSync(join(root, 'src'));
    writeFileSync(join(root, 'build', 'nested', 'literal.js'), Buffer.from('export const script = `a\r\nb`;\n'));
    writeFileSync(join(root, 'build', 'literal.js.map'), Buffer.from('{"version":3}\n'));
    writeFileSync(join(root, 'src', 'literal.ts'), Buffer.from('export const script = `a\r\nb`;\r\n'));
    const inventories = {rootBuild: inventory(join(root, 'build')), rootSource: inventory(join(root, 'src'), {textLF: true})};
    const trees = Object.fromEntries(Object.entries(inventories).map(([name, rows]) => [name, {
        path: name === 'rootBuild' ? 'build' : 'src', files: rows.length, sha256: sha(JSON.stringify(rows)), textLF: name === 'rootSource'}]));
    return {root, directory: 'operator-list-assembly-modeled', inventories,
        observed: {profile: OPERATOR_LIST_PROFILE, trees}, expected: OPERATOR_LIST_ASSEMBLY,
        admission: {status: 'rejected', error: {name: 'AssertionError', message: 'modeled mismatch'}},
        provenance: {scope: 'file-only-modeled-control'}};
}

test('diagnostics retain original CRLF bytes and complete per-file pins without admission authority', t => {
    const value = fixture(t), result = writeAssemblyDiagnostic(value), output = resolve(value.root, value.directory);
    assert.equal(result.admission, 'rejected'); assert.equal(result.qualificationGranted, false);
    const original = readFileSync(join(value.root, 'build', 'nested', 'literal.js'));
    assert.ok(readFileSync(join(output, 'rootBuild', 'nested', 'literal.js')).equals(original));
    assert.ok(original.includes(Buffer.from('\r\n')));
    const assessment = json(join(output, 'assessment.json')), index = json(join(output, 'index.json'));
    assert.deepEqual(assessment.observed, value.observed); assert.deepEqual(assessment.expected, OPERATOR_LIST_ASSEMBLY);
    assert.equal(index.collection, 'complete'); assert.equal(index.admission.status, 'rejected');
    assert.equal(index.inventorySha256, value.observed.trees.rootBuild.sha256); assert.equal(index.files, 2);
    assert.equal(index.qualificationGranted, false); assert.deepEqual(json(join(output, 'inventories.json')).trees, value.inventories);
    for (const row of index.payloads) {
        const bytes = readFileSync(join(output, row.path)); assert.equal(bytes.length, row.bytes); assert.equal(sha(bytes), row.sha256);
    }
    assert.equal(index.payloads.length, 4); assert.equal(index.payloads.some(row => row.path === 'index.json'), false);
    assert.throws(() => writeAssemblyDiagnostic(value), /EEXIST/);
});

test('changed original emissions and oversized raw inventories never receive a complete marker', t => {
    const changed = fixture(t); writeFileSync(join(changed.root, 'build', 'nested', 'literal.js'), 'changed');
    assert.throws(() => writeAssemblyDiagnostic(changed), /original file size changed/);
    assert.equal(existsSync(join(changed.root, changed.directory, 'index.json')), false);
    assert.equal(json(join(changed.root, changed.directory, 'assessment.json')).admission.status, 'rejected');
    const oversized = fixture(t), rows = [{path: 'large.js', bytes: 64 * 1024 * 1024 + 1, sha256: 'a'.repeat(64)}];
    oversized.inventories.rootBuild = rows; oversized.observed.trees.rootBuild.files = 1;
    oversized.observed.trees.rootBuild.sha256 = sha(JSON.stringify(rows));
    assert.throws(() => writeAssemblyDiagnostic(oversized), /raw byte bound/);
    assert.equal(existsSync(join(oversized.root, oversized.directory, 'index.json')), false);
});

test('unsafe and stale diagnostic destinations refuse before emission reads', () => {
    for (const value of ['', '../escape', 'operator-list-assembly-../escape', 'operator-list-assembly-a\\b', '/absolute', 'build',
        'operator-list-assembly-' + 'a'.repeat(97)]) assert.throws(() => diagnosticDirectory(value));
    for (const value of ['', '../x', 'a/../b', '/a', 'a//b', 'a\\b', 'C:/x', 'a/./b', 'a/\0b']) {
        assert.throws(() => diagnosticRelativePath(value));
    }
    assert.equal(diagnosticDirectory('operator-list-assembly-24.22.1'), 'operator-list-assembly-24.22.1');
    assert.equal(diagnosticRelativePath('nested/file.js'), 'nested/file.js');
    assert.throws(() => diagnoseOperatorListAssembly('../escape'), /fresh operator-list-assembly/);
});

test('an admission error remains primary when capture fails and successful collection cannot admit it', () => {
    const primary = new Error('original assembly mismatch'), secondary = new Error('diagnostic disk error');
    let observed;
    assert.throws(() => retainAdmission(() => {throw primary;}, verdict => {observed = verdict;}), error => error === primary);
    assert.equal(observed.status, 'rejected'); assert.equal(observed.error.message, primary.message);
    assert.throws(() => retainAdmission(() => {throw primary;}, () => {throw secondary;}), error => error === primary);
    assert.equal(primary.diagnosticFailure, secondary);
    assert.throws(() => retainAdmission(() => 'admitted assembly', () => {throw secondary;}), error => error === secondary);
    assert.equal(retainAdmission(() => 'admitted assembly', verdict => assert.equal(verdict.status, 'admitted')), 'admitted assembly');
});

test('workflow retains failed raw assembly diagnostics before the physical step while old profile stays frozen', () => {
    const workflow = restoreSdk49Routing('.github/workflows/build.yml', readFileSync(new URL('../../../.github/workflows/build.yml', import.meta.url), 'utf8'));
    const dedicated = workflow.slice(workflow.indexOf('\n  operator-lists-mongodb:'), workflow.indexOf('\n  action-sequences-design:'));
    assert.ok(dedicated.includes('sdk49-source-profile.mjs --diagnostics operator-list-assembly-${{ matrix.node-version }}'));
    assert.ok(dedicated.includes('operator-list-assembly-${{ matrix.node-version }}/'));
    assert.ok(dedicated.indexOf('sdk49-source-profile.mjs --diagnostics') < dedicated.indexOf('operator-list-mongodb/ci.mjs'));
    const successor = readFileSync(new URL('./sdk49-source-profile.mjs', import.meta.url), 'utf8');
    assert.ok(successor.includes('retainAdmission(')); assert.ok(successor.includes('writeAssemblyDiagnostic('));
    assert.ok(dedicated.includes('if: always()')); assert.equal(OPERATOR_LIST_ASSEMBLY.trees.rootBuild.sha256,
        '6fdcae1f6f79a2dda709dc574f28a8888985c4f8bc18071aeffe73dd951ab419');
});

// Stop-capable CI controller. Never import/execute this file for local pure controls.
import assert from 'node:assert/strict';
import {execFileSync, spawn} from 'node:child_process';
import {createWriteStream, existsSync, mkdirSync, readFileSync, realpathSync, writeFileSync} from 'node:fs';
import {release} from 'node:os';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {MongoClient} from 'mongodb';
import {OwnedMongoFixture, MONGODB_IMAGE, MONGODB_VERSION, waitForMongo} from '../projection-fixture.mjs';
import {terminalChild} from '../stateful-complete-kind-mongodb/ci.mjs';
import {PLAN, failure, sha, assertNativeCompletion, assertOriginalTerminal, afterReadiness} from './contract.mjs';
import {admitOperatorListAssembly, OPERATOR_LIST_ASSEMBLY} from './current-cbfb-source-profile.mjs';
const json = (path, value) => writeFileSync(path, JSON.stringify(value, null, 2) + '\n', {flag: 'wx'});
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');

/** Fixed disposable fixture only. No server URI, image, container or resource override is accepted. */
export async function runCI(output) {
    assert.equal(process.env.GITHUB_ACTIONS, 'true', 'This controller is GitHub CI only; bare-metal admission is separate');
    assert.equal(process.platform, 'linux'); assert.equal(process.arch, 'x64');
    assert.equal(realpathSync(process.env.GITHUB_WORKSPACE), realpathSync(root));
    assert.equal(MONGODB_VERSION, PLAN.server); assert.equal(MONGODB_IMAGE, OPERATOR_LIST_ASSEMBLY.fixture.image);
    assert.ok(!existsSync(output)); mkdirSync(output, {recursive: true});
    const fixture = new OwnedMongoFixture(), report = {schemaVersion: 1, scope: PLAN.scope, status: 'running', run: fixture.run,
        profile: PLAN.profile, plan: PLAN, image: MONGODB_IMAGE, mongodb: MONGODB_VERSION, kernel: release(),
        cleanup: fixture.cleanupResult, HAPIOnSend: 'pending', AtomicParity: 'pending', WireReplay: 'separate-pending'};
    let original, child;
    const stop = () => {original ??= new Error('Operator-list CI controller interrupted'); child?.kill('SIGTERM');};
    const check = () => {if (original) throw original;};
    process.once('SIGINT', stop); process.once('SIGTERM', stop);
    try {
        check();
        // Exact new root741/native429/native45 admission precedes every Docker command.
        report.assembly = admitOperatorListAssembly(PLAN.profile);
        const source = process.env.GITHUB_SHA; assert.match(source, /^[a-f0-9]{40}$/);
        const git = args => execFileSync('git', args, {cwd: root, encoding: 'utf8'}).trim();
        report.checkout = {commit: git(['rev-parse', 'HEAD']), tree: git(['rev-parse', 'HEAD^{tree}'])};
        assert.equal(report.checkout.commit, source, 'CI checkout differs from the original workflow source');
        assert.equal(git(['status', '--porcelain=v1', '--untracked-files=all', '--', 'src', 'package.json', 'package-lock.json', 'tsconfig.json',
            '.bun-version', 'packages/backend-mongodb', '.github/workflows/build.yml', 'scripts/qualification/operator-list-mongodb',
            'scripts/qualification/projection-fixture.mjs', 'scripts/qualification/stateful-complete-kind-mongodb/ci.mjs',
            'tests/unit/stateful-engineering-source-admission.mjs']), '', 'Unreviewed CI/product source changes');
        check(); const kernel = fixture.command(['info', '--format', '{{.KernelVersion}}']); report.dockerKernel = kernel;
        const version = /^(\d+)\.(\d+)\.(\d+)/.exec(kernel);
        assert.ok(!version || !(Number(version[1]) === 6 && Number(version[2]) >= 19
            || Number(version[1]) === 7 && Number(version[2]) === 0 && Number(version[3]) < 14), 'MongoDB 8.0.34 kernel constraint');
        check(); fixture.prepare(); check(); const uri = fixture.start('replica');
        const ready = async primary => {
            const client = await waitForMongo(() => {check(); return new MongoClient(uri, {directConnection: true, retryReads: false, retryWrites: false,
                maxAdaptiveRetries: 0, maxPoolSize: 1, serverSelectionTimeoutMS: 1000, connectTimeoutMS: 1000});},
            {primary, replicaSet: fixture.replicaSet, timeoutMS: 60000});
            // Closing an already-acquired readiness client remains required after interruption.
            await client.close();
            check();
        };
        await afterReadiness(check, () => ready(false), () => fixture.initializeReplica());
        report.child = await afterReadiness(check, () => ready(true), () => {
            const owned = fixture.ownedContainer('replica'), image = fixture.inspect('image', MONGODB_IMAGE);
            assert.equal(image.Os, 'linux'); assert.equal(image.Architecture, 'amd64'); assert.equal(owned.Image, image.Id);
            assert.equal(owned.HostConfig.NanoCpus, OPERATOR_LIST_ASSEMBLY.fixture.nanoCPUs);
            assert.equal(owned.HostConfig.Memory, OPERATOR_LIST_ASSEMBLY.fixture.memoryBytes);
            report.container = {id: owned.Id, name: owned.Name, labels: owned.Config.Labels, imageId: image.Id, repoDigests: image.RepoDigests,
                replicaSet: fixture.replicaSet, volume: fixture.volume.name, cpus: owned.HostConfig.NanoCpus, memory: owned.HostConfig.Memory,
                memorySwap: owned.HostConfig.MemorySwap, port: owned.NetworkSettings.Ports};
            const runner = fileURLToPath(new URL('./runner.mjs', import.meta.url));
            check();
            // Publish the child handle and attach its terminal collector in this same synchronous turn.
            child = spawn(process.execPath, [runner, '--run', '--allow-failpoints', '--database', 'h45_lists_' + fixture.run.slice(0, 12),
                '--output', join(output, 'native'), '--source', source, '--compiled-sha256', OPERATOR_LIST_ASSEMBLY.trees.nativeBuild.sha256],
            {stdio: ['ignore', 'pipe', 'pipe'], env: {...process.env, HYPERION_OPERATOR_LIST_MONGO_URI: uri + '&replicaSet=' + fixture.replicaSet}});
            // Existing owned-fixture terminal/stream collector retains its original 300s + failure-only grace.
            return terminalChild(child, createWriteStream(join(output, 'runner.stdout.log'), {flags: 'wx'}),
                createWriteStream(join(output, 'runner.stderr.log'), {flags: 'wx'}),
                {deadlineMS: OPERATOR_LIST_ASSEMBLY.fixture.childDeadlineMS, graceMS: OPERATOR_LIST_ASSEMBLY.fixture.graceMS,
                    terminalMS: OPERATOR_LIST_ASSEMBLY.fixture.terminalMS});
        });
        check();
        assertOriginalTerminal(report.child);
        const native = JSON.parse(readFileSync(join(output, 'native/report.json')));
        assertNativeCompletion(report.child, native, OPERATOR_LIST_ASSEMBLY.trees.nativeBuild.sha256);
        const checksums = JSON.parse(readFileSync(join(output, 'native/sha256.json')));
        assert.deepEqual(checksums.map(row => row.path).sort(), ['report.json', 'trace.json']);
        for (const entry of checksums) {
            const body = readFileSync(join(output, 'native', entry.path)); assert.equal(body.length, entry.bytes); assert.equal(sha(body), entry.sha256);
        }
        report.native = {status: native.status, cases: native.cases.length, traceEvents: native.traceEvents, checkedRawArtifacts: checksums};
    } catch (error) {original ??= error; report.failure = failure(original); if (error !== original) report.secondaryFailure = failure(error);}
    finally {
        try {report.diagnostics = fixture.diagnostics(); json(join(output, 'before-cleanup.json'), report);}
        catch (error) {original ??= error; report.evidenceFailure = failure(error);}
        try {await fixture.cleanup();} catch (error) {original ??= error; report.cleanupFailure = failure(error);}
        process.off('SIGINT', stop); process.off('SIGTERM', stop);
        if (original) report.failure ??= failure(original);
        report.status = original ? 'failed' : 'passed-native-operator-list-only'; json(join(output, 'controller.json'), report);
    }
    if (original) throw original; return report;
}
if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
    assert.equal(process.argv.length, 3, 'Use node ci.mjs NEW_EVIDENCE_DIRECTORY');
    const report = await runCI(resolve(process.argv[2])); console.log(JSON.stringify({status: report.status, run: report.run}));
}

// Pure plan/admission/trace checks; no database, process, network or service operations.
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
export const HISTORICAL_PLAN = Object.freeze({schemaVersion: 1, scope: 'synthetic-native-operator-lists',
    profile: 'operator-list-mongodb-root741-native429-source-9c3db03-linux-gitlf-engineering', rootSDK: '7412889a14c84342551fd864ea3ebfcf28849385',
    sdk: '429a1bf1d3bddb746fa662de9529480890b7368f', driver: '7.2.0', server: '8.0.34',
    operationMS: 5000, snapshotMS: 60000, readMS: 10000, publicationMS: 120000,
    read: {names: 8, items: 2048, bytes: 2 * 1024 * 1024, attempts: 256},
    publication: {names: 128, items: 40000, bytes: 32 * 1024 * 1024, attempts: 8192},
    cache: {names: 128, items: 40000, bytes: 8 * 1024 * 1024}, pageSize: 64, batchDocuments: 64,
    cases: ['partitioned-publication-over-16MiB', 'actual-attempts-and-exhaustion', 'ordinary-revision-cache',
        'empty-missing-and-unavailable', 'whole-read-budgets', 'missing-index-native-failure', 'partial-storage-refusal',
        'concurrent-publication-and-losing-CAS', 'cleanup-attempt-reserve', 'late-cancel-and-retirement', 'blocked-find-deadline', 'original-session-client-cleanup'],
    acceptance: {nativeMongoDB: 'pending-until-run', requestHost: 'pending', finalOnSend: 'pending', AtomicParity: 'pending', WireReplay: 'separate'}});
export const PLAN = Object.freeze({...HISTORICAL_PLAN, profile: 'stateful-sdk49-root-cbfb-native-wire69-linux-engineering-v1', rootSDK: 'dc20a03f2b60ba05a3369d677222a9cf0d65d299', sdk: 'cbfb26694b90b52266d1e0b9b5dbf6f8389e736b'});
export const sha = bytes => createHash('sha256').update(bytes).digest('hex');
export function argumentsFor(argv, environment) {
    assert.equal(argv.length, 10, 'Use --run --allow-failpoints --database NAME --output NEW_DIR --source COMMIT --compiled-sha256 SHA');
    assert.equal(argv[0], '--run'); assert.equal(argv[1], '--allow-failpoints');
    assert.equal(argv[2], '--database'); assert.match(argv[3], /^h45_lists_[a-f0-9]{12}$/);
    assert.equal(argv[4], '--output'); assert.ok(typeof argv[5] === 'string' && argv[5]);
    assert.equal(argv[6], '--source'); assert.match(argv[7], /^[a-f0-9]{40}$/);
    assert.equal(argv[8], '--compiled-sha256'); assert.match(argv[9], /^[a-f0-9]{64}$/);
    const uri = environment.HYPERION_OPERATOR_LIST_MONGO_URI, parsed = new URL(uri);
    assert.equal(parsed.protocol, 'mongodb:'); assert.equal(parsed.hostname, '127.0.0.1');
    assert.equal(parsed.username + parsed.password + parsed.hash, ''); assert.ok(parsed.pathname === '' || parsed.pathname === '/');
    const port = Number(parsed.port); assert.ok(Number.isInteger(port) && port >= 1024 && port <= 65535 && port !== 27017);
    assert.deepEqual([...parsed.searchParams.keys()].sort(), ['directConnection', 'replicaSet']);
    assert.equal(parsed.searchParams.get('directConnection'), 'true');
    const replicaSet = parsed.searchParams.get('replicaSet'); assert.match(replicaSet, /^(?:h45_[a-z0-9_]{1,40}|h45rs_[a-f0-9]{32})$/);
    return {uri, database: argv[3], output: argv[5], source: argv[7], compiledSha256: argv[9], replicaSet,
        member: replicaSet.startsWith('h45rs_') ? 'hyp-projection-' + replicaSet.slice(6) + '-replica:27017' : '127.0.0.1:' + port};
}
export function verifyReadTrace(trace, phase, {attempts, maximum, success = false, pageSize = PLAN.pageSize} = {}) {
    const data = trace.filter(row => row.phase === phase && row.event === 'started' && row.tagged && ['find', 'aggregate', 'getMore', 'killCursors'].includes(row.command));
    assert.ok(data.length <= maximum, 'Actual read attempt allowance exceeded');
    if (attempts !== undefined) assert.equal(data.length, attempts, 'Reported native attempts differ from actual commands');
    for (const row of data) {
        assert.equal(row.transactional, false); assert.ok(row.lsid && row.txn === null && row.traceId);
        const start = data.find(item => item.client === row.client && item.traceId === row.traceId && item.command !== 'killCursors');
        assert.ok(start && start.seq <= row.seq && start.readConcern === 'snapshot' && start.lsid === row.lsid, 'No actual snapshot start for native read');
        const reply = trace.find(item => item.event === 'succeeded' && item.requestId === row.requestId && item.client === row.client);
        if (row.command === 'killCursors') {
            // Cleanup is not a snapshot data read. The same original identity and a
            // successful reply must instead prove closure of every original live cursor.
            assert.equal(row.readConcern, null, 'Cursor cleanup cannot carry readConcern');
            assert.equal(row.atClusterTime, null, 'Cursor cleanup cannot carry atClusterTime');
            assert.ok(typeof row.collection === 'string' && row.collection.length > 0, 'Cleanup namespace is missing');
            const owned = new Set();
            for (const prior of data.filter(item => item.seq < row.seq && item.client === row.client && item.lsid === row.lsid
                && item.traceId === row.traceId && item.collection === row.collection)) {
                const response = trace.find(item => item.event === 'succeeded' && item.requestId === prior.requestId
                    && item.client === prior.client && item.seq > prior.seq && item.seq < row.seq);
                if (prior.command === 'getMore') assert.ok(owned.has(prior.cursor), 'Cleanup sequence lost its original cursor');
                if (prior.command === 'killCursors') {
                    for (const id of [...response.cursorClosure.cursorsKilled, ...response.cursorClosure.cursorsNotFound]) owned.delete(id);
                } else if (response?.cursor === '0' && prior.command === 'getMore') owned.delete(prior.cursor);
                else if (typeof response?.cursor === 'string' && response.cursor !== '0') owned.add(response.cursor);
            }
            assert.ok(owned.size > 0 && reply && reply.seq > row.seq, 'No original live cursor or successful cleanup response');
            const terminal = new Set();
            for (const name of ['cursorsKilled', 'cursorsNotFound', 'cursorsAlive', 'cursorsUnknown']) {
                const ids = reply.cursorClosure?.[name];
                assert.ok(Array.isArray(ids) && ids.length <= owned.size, 'Malformed cursor-closure response');
                if (name === 'cursorsAlive' || name === 'cursorsUnknown') assert.deepEqual(ids, [], 'Native cursor cleanup is incomplete');
                for (const id of ids) {
                    assert.ok(owned.has(id) && !terminal.has(id), 'Foreign or duplicate native cursor closure'); terminal.add(id);
                }
            }
            assert.equal(terminal.size, owned.size, 'Original native cursor closure is incomplete');
        } else if (row.seq !== start.seq) {
            const established = trace.find(item => item.event === 'succeeded' && item.client === start.client && item.requestId === start.requestId);
            assert.ok(established?.snapshotTime && row.atClusterTime === established.snapshotTime && row.readConcern === 'snapshot', 'Native snapshot time changed or was not carried forward');
        }
        if (row.command !== 'killCursors') assert.equal(row.batchSize, pageSize);
        if (row.command === 'getMore' || row.command === 'killCursors') assert.equal(row.maxTimeMS, null, 'Non-tailable cursor control cannot have maxTimeMS');
        else assert.ok(row.maxTimeMS > 0 && row.maxTimeMS <= PLAN.operationMS);
        if (success) assert.ok(reply, 'Missing successful original command response');
        if (reply?.cursor !== undefined) assert.ok(reply.batch <= pageSize);
        if (success && row.command !== 'killCursors' && reply && reply.cursor !== '0') {
            assert.ok(data.some(next => next.seq > row.seq && next.command === 'getMore' && next.cursor === reply.cursor), 'Successful read hid an unexhausted cursor');
        }
    }
    assert.equal(trace.filter(row => row.phase === phase && row.event === 'started' && ['commitTransaction', 'abortTransaction'].includes(row.command)).length, 0,
        'Snapshot list reads must not hide transaction completion/retry commands');
    if (success && data.length) {
        const final = data.at(-1), response = trace.find(row => row.event === 'succeeded' && row.requestId === final.requestId && row.client === final.client);
        assert.notEqual(final.command, 'killCursors', 'Cleanup cannot substitute for complete native exhaustion');
        assert.equal(response?.cursor, '0', 'Complete result lacks native exhaustion');
    }
    return {attempts: data.length, replyBsonBytes: trace.filter(row => row.phase === phase && row.event === 'succeeded').reduce((n, row) => n + row.replyBsonBytes, 0)};
}
export function failure(error, depth = 0) {
    return {name: String(error?.name ?? 'Error').slice(0, 64), code: typeof error?.code === 'string' || Number.isSafeInteger(error?.code) ? error.code : null,
        message: String(error?.message ?? 'Unknown fixture failure').slice(0, 512),
        ...(error?.cause && depth < 2 ? {cause: failure(error.cause, depth + 1)} : {}),
        ...(Array.isArray(error?.suppressed) && depth < 2 ? {suppressed: error.suppressed.slice(0, 4).map(item => failure(item, depth + 1))} : {})};
}
export function assertOriginalTerminal(terminal) {
    assert.equal(terminal.timedOut, false, 'Timeout/grace cannot become a native pass');
    assert.equal(terminal.code, 0); assert.equal(terminal.signal, null); assert.equal(terminal.terminal, true); assert.equal(terminal.streamsClosed, true);
}
/** Pure readiness fence; a recorded interruption cannot authorize the next effect. */
export async function afterReadiness(check, ready, continueWork) {
    check(); await ready(); check(); return continueWork();
}
/** Pure CI verdict check; artifact collection/cleanup cannot replace the original child result. */
export function assertNativeCompletion(terminal, native, compiledSha256) {
    assertOriginalTerminal(terminal);
    assert.equal(native.status, 'passed-native-only'); assert.equal(native.source.profile, PLAN.profile); assert.equal(native.source.compiledSha256, compiledSha256);
    assert.deepEqual(native.cases.map(row => row.name).sort(), PLAN.cases.filter(name => name !== 'original-session-client-cleanup').sort());
    assert.ok(native.cases.every(row => row.status === 'passed'));
